  [96377] = { "Segreti di stato", nil, nil, nil, nil, 0x7294e55b, nil, nil, nil, nil, ".mmmm" },
  [96379] = { "Segreti di stato", nil, nil, nil, nil, 0x7294e55b, nil, nil, nil, nil, ".mmmm" },
  [96381] = { "Un po' di lavoro sporco", "Entra nella Prigione di Alcaz e uccidi $N1 Soldato Strashaz e $N2 Incantatrice Strashaz, poi porta la testa della Signora delle Maree Ca'zass a Sully McCleary.", nil, nil, nil, 0xc062c89e, 0x3abd7349, nil, nil, nil, "..mmm" },
  [96383] = { "Ricompensa dell'eredità: ⟦Spectral Bear Cub=Cucciolo d'Orso Spettrale⟧", nil, nil, nil, nil, 0x282c1e94, nil, nil, nil, nil, ".mmmm" },
  [96390] = { "Stroncarli sul nascere", "Uccidi $N1 Dark Iron Spy a Dun Morogh.", "Delle spie ⟦Dark Iron=Ferroscuro⟧ si sono infiltrate a Dun Morogh. A che scopo non posso dirlo con certezza, ma è un problema che dobbiamo stroncare sul nascere, prima che cresca.\n\nDirigiti a est, verso il ⟦Ironband's Compound=Presidio di Ferrocollo⟧, e uccidi le spie ⟦Dark Iron=Ferroscuro⟧ che trovi lì.", nil, "Questi Ferroscuro saranno anche nostri cugini, ma non sono famiglia, questo è certo. Non verso lacrime per le disgrazie che capitano a quelli che si allontanano troppo da quella loro montagna maledetta.\n\nSperiamo che basti a dissuaderli da altre incursioni in queste terre.", 0x5f38218b, 0x10fb22fa, 0x9db0e0ef, nil, 0xd5731f3e, "...m." },
  [96391] = { "Una mappa dei sotterranei", "Consegna la ⟦Dark Iron Map=Mappa dei Ferroscuro⟧ al veggente della terra Farsen, a Dun Morogh.", "La mappa che hai in mano sembra mostrare una complessa rete di gallerie e strade sotterranee che convergono tutte in un punto proprio sotto ⟦Ironforge=Forgiardente⟧.\n\nNon puoi sapere con certezza cosa dicano le rune, scritte nella brutta e spigolosa lingua runica dei nani ⟦Dark Iron=Ferroscuro⟧, ma puoi intuire lo scopo di queste gallerie. Mentre leggi la mappa, una folata di vento ti investe e senti, debole, una voce nanica portata dal vento. Il veggente della terra Farsen deve vederla.", "Oh, e questo cos'è?", "A giudicare da questa mappa, sembra proprio che questi Ferroscuro stiano preparando una specie di incursione nelle cripte sotto ⟦Ironforge=Forgiardente⟧. La banda che hai sgominato a est dev'essere una forza di ricognizione.\n\nGrazie per avermela portata. Se ci sbrighiamo, forse riusciremo a precederli, qualunque sia il loro obiettivo laggiù.", 0x9d9cce92, 0x0559f95b, 0x9898e535, 0x52844eeb, 0x1c2fe859, "....." },
  [96392] = { "Lo sguardo di Farsen", "Parla con il veggente della terra Farsen e chiedigli di prestarti la sua vista lontana per osservare la minaccia ⟦Dark Iron=Ferroscuro⟧.", "Salute a te, amico. Mi chiamo Farsen, veggente della terra, e sono a Dun Morogh in visita dal ⟦Aerie Peak=Picco dell'Aquila⟧. Mentre viaggiavo, non ho potuto fare a meno di notare che abbiamo, be'... un certo problema di nani Ferroscuro.\n\nSe hai un momento, posso mostrarti cosa intendo. Ho un pizzico di magia che dovrebbe fare al caso nostro.", nil, "Allora, ora capisci, {class}? Sono fitti come scarafaggi, e sono solo quelli che vediamo dal cielo.\n\nMi sembri abbastanza robust<o/a>. Che ne dici di un po' di violenza?", 0x9243cd15, 0x987a4089, 0xce20450c, nil, 0x478676d1, "...m." },
  [96393] = { "Incursione nella Vecchia ⟦Ironforge=Forgiardente⟧", "Entra nella Hall of Thanes sotto la Vecchia ⟦Ironforge=Forgiardente⟧ e prendi la testa di Durgen Dirgehammer.", "Raduna qualche alleato e scendi nelle caverne sotto la Vecchia ⟦Ironforge=Forgiardente⟧. Entra nella Hall of Thanes e spingiti fino alle cripte inferiori.\n\nIl mio ⟦Dark Iron=Ferroscuro⟧ è un po' arrugginito, ma riesco a decifrare un nome: un certo Durgen Dirgehammer. Probabilmente è lui il comandante. Prendi la sua testa e consegnala a re Magni Barbabronzea.\n\nAh, e quando lo fai, digli che il suo vecchio amico Farsen gli manda i suoi saluti!", "Di che cosa hai bisogno, <cittadino/cittadina>?", "Un'incursione ⟦Dark Iron=Ferroscuro⟧... proprio sotto i nostri piedi? Be', è un sollievo sapere che il comandante ⟦Dark Iron=Ferroscuro⟧ è stato eliminato.\n\nLe guardie entreranno a ripulire il resto della marmaglia. Faremo in modo che le brecce vengano sigillate e i livelli inferiori rinforzati, così che nessun'altra incursione sia possibile.\n\nGrazie per il tuo servizio a ⟦Ironforge=Forgiardente⟧, {class}. Accetta questo piccolo pegno della mia gratitudine. Ah, e se rivedi Farsen, quel vecchio Granmartello abbracciarocce, digli di venirmi a trovare come si deve.", 0x48866402, 0xe0bec594, 0xa08604c5, 0xa75dc075, 0x0fc00f59, "....." },
  [96394] = { "I morti senza pace", "Uccidi $N1 Enraged Apparition e $N2 Tormented Soul, e dai riposo allo spirito del thane ⟦Anvilmar=Forgiamara⟧.", "Qualcosa ha disturbato le tombe giù nella Hall of Thanes, e dal profondo delle cripte si sentono strani rumori. Gli spiriti dei morti hanno il sonno leggero, e qualunque cosa stia succedendo laggiù sembra averli spaventati.\n\nScendi laggiù e vedi cosa puoi fare per noi. Se qualche morto si è svegliato... be', rimettilo a dormire!", nil, "Ah, bene, allora è fatta. Non posso permettere che gli altri custodi si rifiutino di entrare nella sala a fare il loro dovere per colpa di «fantasmi» e «morti arrabbiati», no?", 0x69066003, 0x6a43847e, 0xd9e1bd9c, nil, 0x1d4545a7, "...m." },
  [96395] = { "Un antico rancore", "Dai riposo allo spirito di Faldrim ⟦Anvilmar=Forgiamara⟧, poi torna dal Ghostly Attendant nella Hall of Thanes.", "Il... thane... il mio potente... thane... ha... bisogno di... riposare.\n\nTi prego... aiutalo... aiutalo... a riposare...\n\nConsumato... da un... antico... rancore... Nessun... riposo...", "<La figura spettrale fissa il vuoto oltre di te. La sua bocca si muove, ma si sentono solo bassi rantoli indistinti.>", "Il mio... thane... riposa... sì... riposa.\n\nGrazie... a te...\n\nIo... riposo...", 0x372fadb2, 0xf47ad935, 0x22f3d060, 0x36b0ce0b, 0x80ede96a, "....." },
  [96403] = { "Cimeli importanti", "Raccogli $N1 Dwarven Heirloom nella Hall of Thanes.", "Ehi, tu, <avventuriero/avventuriera>... mi servirebbe proprio il tuo aiuto.\n\nStavo sgattaiolando... ehm... «pattugliando» le cripte, quando una squadra di nani ⟦Dark Iron=Ferroscuro⟧ è sbucata dalle profondità a bordo di talpe meccaniche! Non so cosa siano venuti a fare, ma laggiù c'è un bottino inestimabile... ehm, o meglio... voglio dire, ci sono «importanti cimeli culturali»! Ti prego, recupera tutti i reperti di questo tipo che vedi e riportali qui.\n\nTi assicuro che tutto ciò che recupererai sarà catalogato e restituito al suo legittimo posto d'onore.", "<Thom si sfrega distrattamente le mani mentre ti guarda.>", "Ma guardati, coraggios<o/a> quanto intraprendente! Sono uno gnomo di parola, e la tua ricompensa è ben meritata!\n\nOra fammi dare un'occhiata al bottino... ehm, voglio dire... ai cimeli recuperati. Devo cominciare a valutarli... pardon, a «catalogarli», così da poterli rimettere al loro posto il prima possibile.", 0xdb5e0561, 0x7bf6ecf5, 0x1019355e, 0xb065081e, 0xd63d4304, "....." },
  [96408] = { "Un visitatore a Dun Morogh", "Ispeziona l'accampamento che domina la ⟦Gol'Bolar Quarry=Cava di Gol'Bolar⟧.", "Ieri notte uno dei nostri montanari ha avvistato un fuoco da campo su un pendio a est. Sembra piuttosto in alto, sopra la ⟦Gol'Bolar Quarry=Cava di Gol'Bolar⟧.\n\nProbabilmente non è niente, ma vorrei che andassi a dare un'occhiata a quell'accampamento. Se sono amici, nessun danno. Se non lo sono... be', sai cosa fare.", nil, "Salute, amico. Come va?", 0x7b3a9976, 0x89d2ded4, 0x1a6a0853, nil, 0x9c8725d7, "...m." },
  [96435] = { "Una fine appropriata", "Getta le ossa dello stregone nel mucchio di ossa vicino alle pozze di melma.", nil, nil, nil, 0x9ccc7a6b, 0x95eef7e8, nil, nil, nil, "..mmm" },
  [96438] = { "Battaglia alla ⟦Mannoroc Coven=Congrega di Mannoroc⟧", "Indaga sulla battaglia alla ⟦Mannoroc Coven=Congrega di Mannoroc⟧ a ⟦Desolace=Desolanda⟧.", nil, nil, nil, 0x16f8ad12, 0x53828f2a, nil, nil, nil, "..mmm" },
  [96449] = { "Il rifugio segreto di Aeonas", "Usa la vecchia barchetta al ⟦Menethil Harbor=Porto di Menethil⟧ per cercare Aeonas.", nil, nil, nil, 0xfec7166c, 0x2ce13332, nil, nil, nil, "..mmm" },
  [96476] = { "Alla ricerca di Aeonas", "Cerca tracce di Aeonas il Vendicato al ⟦Emerald Sanctuary=Santuario di Smeraldo⟧ a ⟦Felwood=Vilbosco⟧.", nil, nil, nil, 0xaf8071c4, 0xbac5a578, nil, nil, nil, "..mmm" },
  [96494] = { "Si addensa la tempesta", "Trova il punto di rinforzo degli Spinanera all'ingresso della Sommità di Hyjal.", nil, nil, nil, 0xe5c57e46, 0xc6ea4966, nil, nil, nil, "..mmm" },
  [96529] = { "Un affare alla Shaw", "Porta le Informazioni sugli Spinanera al ⟦Master Mathias Shaw=Maestro Mathias Shaw⟧ a ⟦Stormwind=Roccavento⟧.", nil, nil, nil, 0x00c54442, 0xbb26a5a5, nil, nil, nil, "..mmm" },
  [96550] = { "Richiamo in battaglia", "Usa il Fodero Ricamato per parlare con il veterano di guerra e ascoltare la sua storia al belvedere della Selva Antica.", nil, nil, nil, 0xae620b44, 0x877f7c07, nil, nil, nil, "..mmm" },
  [96558] = { "Conforto del soldato", "Recupera la Scorta da Battaglia sepolta sul ⟦Mount Hyjal=Monte Hyjal⟧.", nil, nil, nil, 0xe607edf5, 0x69f605f5, nil, nil, nil, "..mmm" },
  [96559] = { "Lancio di rifornimenti", "Trova il Kit di Sopravvivenza del Pilota di Fenwick Mollascatto.", nil, nil, nil, 0xf9b68c03, 0xc4da7a46, nil, nil, nil, "..mmm" },
  [96561] = { "Ultimi desideri", "Trova lo stagno di pesca vicino alla segheria distrutta dell'⟦Alliance=Alleanza⟧ nella Culla della Tranquillità.", nil, nil, nil, 0x4174693e, 0x4ad04d6d, nil, nil, nil, "..mmm" },
  [96602] = { "Altra magia instabile", nil, nil, nil, nil, 0x21b0f176, nil, nil, nil, nil, ".mmmm" },
  [96603] = { "Magia instabile", "Porta $N1 Particella di Magia Instabile all'Arcimago Celindra a Dalaran.", nil, nil, nil, 0xd9f44e11, 0x5b11ae4f, nil, nil, nil, "..mmm" },
  [96604] = { "La vita all'aria aperta", "Siediti vicino al ⟦Brakk's Basic Campfire=Fuoco da Campo Semplice di Brakk⟧ e attendi di ricevere il beneficio ⟦Boosted Rest=Riposo Potenziato⟧.", "Lok-tar, {class}. Hai proprio l'aria dell'avventuriero, e questo è un bene. Il mondo ha bisogno di altre anime irrequiete come noi, in cerca di fortuna e di gloria.\n\nIn questo mestiere, per avere successo, dovrai imparare a cavartela nelle terre selvagge. Non so quanto tu sia <bravo/brava> all'aperto, ma qualcosa probabilmente posso insegnartelo, se hai voglia di imparare.\n\nSiediti vicino al fuoco e mettiti comod<o/a>. Ti spiego io come si fa.", nil, "Ora che abbiamo imparato le basi, va' a imparare un mestiere dagli istruttori del villaggio qui vicino. Ti insegneranno anche a costruire un'attrezzatura da accampamento adatta alla tua nuova professione.", 0x561c5fa2, 0xc9a7eaed, 0x1dfc83c1, nil, 0xeab943b1, "...m." },
  [96605] = { "La vita all'aria aperta", "Siediti vicino al ⟦Kaga's Basic Campfire=Fuoco da Campo Semplice di Kaga⟧ e attendi di ricevere il beneficio ⟦Boosted Rest=Riposo Potenziato⟧.", "Salute, {class}. Si vede che hai l'aria dell'avventuriero. Questo è un bene. Il mondo ha bisogno di più anime irrequiete come noi, in cerca di fortuna e di gloria.\n\nPer avere successo in questo mestiere dovrai imparare a prosperare nelle terre selvagge. Non so quanto tu sia pratic<o/a> di vita all'aperto, ma probabilmente posso insegnarti un paio di cose, se hai voglia di imparare.\n\nSiediti vicino al fuoco e mettiti comod<o/a>. Ti spiego tutto io.", nil, "Ora che abbiamo imparato le basi, perché non vai a imparare un mestiere dagli istruttori del villaggio qui vicino? Ti insegneranno anche a costruire un'attrezzatura da accampamento adatta alla tua nuova professione.", 0x561c5fa2, 0x6d44875e, 0xb221e6cb, nil, 0x2eacf33d, "...m." },
  [96606] = { "La vita all'aria aperta", "Siediti vicino al ⟦Lyreena's Basic Campfire=Fuoco da Campo Semplice di Lyreena⟧ e attendi di ricevere il beneficio ⟦Boosted Rest=Riposo Potenziato⟧.", "Salute, {class}. Si vede che hai l'aria dell'avventuriero. Questo è un bene. Il mondo ha bisogno di più anime irrequiete come noi, in cerca di fortuna e di gloria.\n\nPer avere successo in questo mestiere dovrai imparare a prosperare nelle terre selvagge. Non so quanto tu sia pratic<o/a> di vita all'aperto, ma probabilmente posso insegnarti un paio di cose, se hai voglia di imparare.\n\nSiediti vicino al fuoco e mettiti comod<o/a>. Ti spiego tutto io.", "Possedere le abilità necessarie per sopravvivere all'aperto è fondamentale. Un avventuriero ben riposato e ben preparato ha molte più probabilità di sopravvivere a questo stile di vita.", "Ora che abbiamo imparato le basi, perché non vai a imparare un mestiere dagli istruttori del villaggio qui vicino? Ti insegneranno anche a costruire un'attrezzatura da accampamento adatta alla tua nuova professione.", 0x561c5fa2, 0xbbb8647e, 0xb221e6cb, 0x452722a2, 0x2eacf33d, "....." },
  [96607] = { "La vita all'aria aperta", "Siediti vicino al ⟦Eleanor's Basic Campfire=Fuoco da Campo Semplice di Eleanor⟧ e attendi di ricevere il beneficio ⟦Boosted Rest=Riposo Potenziato⟧.", "Salute, {class}. Si vede che hai l'aria dell'avventuriero. Questo è un bene. Il mondo ha bisogno di più anime irrequiete come noi, in cerca di fortuna e di gloria.\n\nPer avere successo in questo mestiere dovrai imparare a prosperare nelle terre selvagge. Non so quanto tu sia pratic<o/a> di vita all'aperto, ma probabilmente posso insegnarti un paio di cose, se hai voglia di imparare.\n\nSiediti vicino al fuoco e mettiti comod<o/a>. Ti spiego tutto io.", nil, "Ora che abbiamo imparato le basi, perché non vai a imparare un mestiere dagli istruttori del villaggio qui vicino? Ti insegneranno anche a costruire un'attrezzatura da accampamento adatta alla tua nuova professione.", 0x561c5fa2, 0x71b45cb3, 0xb221e6cb, nil, 0x2eacf33d, "...m." },
  [96608] = { "La vita all'aria aperta", "Siediti vicino al ⟦Eric's Basic Campfire=Fuoco da Campo Semplice di Eric⟧ e attendi di ricevere il beneficio ⟦Boosted Rest=Riposo Potenziato⟧.", "Salute, {class}. Si vede che hai l'aria dell'avventuriero. Questo è un bene. Il mondo ha bisogno di più anime irrequiete come noi, in cerca di fortuna e di gloria.\n\nPer avere successo in questo mestiere dovrai imparare a prosperare nelle terre selvagge. Non so quanto tu sia pratic<o/a> di vita all'aperto, ma probabilmente posso insegnarti un paio di cose, se hai voglia di imparare.\n\nSiediti vicino al fuoco e mettiti comod<o/a>. Ti spiego tutto io.", nil, "Ora che abbiamo imparato le basi, perché non vai a imparare un mestiere dagli istruttori del villaggio qui vicino? Ti insegneranno anche a costruire un'attrezzatura da accampamento adatta alla tua nuova professione.", 0x561c5fa2, 0x2837fcc0, 0xb221e6cb, nil, 0x2eacf33d, "...m." },
  [96609] = { "Il sapore di casa", "Porta $N1 bottiglie di Vino Scintillante di Lunargenta ad Arille Sguardazzurro nella città di Dalaran.", nil, nil, nil, 0x2177fad0, 0xe0add89f, nil, nil, nil, "..mmm" },
  [96616] = { "Erbe per i contusi e gli stanchi", "Raccogli $N1 Silfio di Hyjal.", nil, nil, nil, 0xc834be5b, 0x8e03a19a, nil, nil, nil, "..mmm" },
  [96622] = { "Un riposo senza dolore", "Consegna l'Impiastro di Silfio di Hyjal a Enho e Maruke.", nil, nil, nil, 0xb9e4ceb9, 0xc848e3e9, nil, nil, nil, "..mmm" },
  [96626] = { "⟦Camping=Campeggio⟧ 101: Cucina", "Parla con Tomas a ⟦Goldshire=Borgodoro⟧ per imparare a cucinare.", "Così vuoi saperne di più sull'arte di accamparsi, eh? Ottima idea, {class}. Il primo passo per ogni avventuriero è imparare a cucinare e ad accendere un fuoco da campo.\n\nCucinare non serve solo a preparare piatti gustosi: è anche la base del tuo accampamento.", "Un buon fuoco da campo è la base di ogni buon accampamento.", "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Quello che hai imparato sono solo le basi, quindi non potrai sistemarci intorno troppi arredi.\n\nMigliora la tua abilità in Cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti dagli istruttori di altre professioni, se te la cavi nelle loro arti.", 0x61f383d0, 0x48b91f09, 0x611be1a4, 0x20282ef3, 0x4d6e308e, "....." },
  [96627] = { "Vita da avventuriero", "Parla con Sam Sarsparilla nei pressi di ⟦Goldshire=Borgodoro⟧.", "{name}, finora hai dimostrato il tuo valore come protett<ore/rice>. Per questo ora ti affido un compito insolito.\n\nHo sentito parlare di un nuovo avventuriero lungo la strada, vicino a ⟦Goldshire=Borgodoro⟧. Va' a vedere che cosa sta facendo.", nil, "Grazie per esserti preoccupat<o/a> per me, {class}. Quel maresciallo si agita per niente.\n\nEhi, anche tu hai l'aria dell'avventuriero. Ti andrebbe di imparare ad accamparti?", 0x1afc3318, 0x24f0776f, 0x24463491, nil, 0xeb1c22f1, "...m." },
  [96628] = { "Vita da avventuriero", "Consegna il ⟦Supply Bundle=Fagotto di Rifornimenti⟧ a ⟦Eric Brighthammer=Eric Martello Lucente⟧ nei pressi di Kharanos.", "Aspetta, {name}. Ho un'altra richiesta da farti, prima che tu affronti quella galleria.\n\nI miei montanari hanno segnalato un avventuriero comparso appena fuori Kharanos. Potresti consegnargli queste provviste?", "Sei qui per imparare ad accamparti nelle terre selvagge?", "Dici che vengono dai montanari? Sì, mi fanno comodo. Grazie, {class}.\n\nEhi, anche tu hai l'aria dell'avventuriero. Ti andrebbe di imparare ad accamparti?", 0x1afc3318, 0xbfabdfa9, 0x1f02236b, 0xf7a7f9bd, 0x5f83030c, "....." },
  [96629] = { "⟦Camping=Campeggio⟧ 101: Cucina", "Parla con Gremlock Pilsnor a Kharanos per imparare a cucinare.", "Così vuoi saperne di più sull'arte di accamparsi, eh? Ottima idea, {class}. Il primo passo per ogni avventuriero è imparare a cucinare e ad accendere un fuoco da campo.\n\nCucinare non serve solo a preparare piatti gustosi: è anche la base del tuo accampamento.", "Un buon fuoco da campo è la base di ogni buon accampamento.", "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Quello che hai imparato sono solo le basi, quindi non potrai sistemarci intorno troppi arredi.\n\nMigliora la tua abilità in Cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti dagli istruttori di altre professioni, se te la cavi nelle loro arti.", 0x61f383d0, 0xfb18b446, 0x611be1a4, 0x20282ef3, 0x4d6e308e, "....." },
  [96630] = { "Vita da avventuriero", "Porta il diario a ⟦Lyreena Duskblade=Lyreena Lama del Vespro⟧ nei pressi di Dolanaar.", "<Il diario sembra piuttosto ordinario: racconta la vita e le avventure di qualcuno di cui non hai mai sentito parlare.\n\nDiverse pagine parlano di campeggio. Sembra proprio... divertente.>", "Sei qui per imparare ad accamparti nelle terre selvagge?", "È il mio diario? Era da un po' che non lo trovavo più. Grazie, {class}.\n\nEhi, anche tu hai l'aria dell'avventuriero. Ti andrebbe di imparare ad accamparti?", 0x1afc3318, 0xc5322669, 0xfeee01ed, 0xf7a7f9bd, 0xd8b07e29, "....." },
  [96634] = { "⟦Camping=Campeggio⟧ 101: Cucina", "Parla con Zarrin a Dolanaar per imparare a cucinare.", "Così vuoi saperne di più sull'arte di accamparsi, eh? Ottima idea, {class}. Il primo passo per ogni avventuriero è imparare a cucinare e ad accendere un fuoco da campo.\n\nCucinare non serve solo a preparare piatti gustosi: è anche la base del tuo accampamento.", "Un buon fuoco da campo è la base di ogni buon accampamento.", "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Quello che hai imparato sono solo le basi, quindi non potrai sistemarci intorno troppi arredi.\n\nMigliora la tua abilità in Cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti dagli istruttori di altre professioni, se te la cavi nelle loro arti.", 0x61f383d0, 0xa03560df, 0x611be1a4, 0x20282ef3, 0x4d6e308e, "....." },
  [96638] = { "Vita da avventuriero", "Parla con ⟦Raan Wildwind=Raan Ventoteso⟧ nei pressi del ⟦Shen'dar Village=Villaggio di Shen'dar⟧.", "Sempre più avventurieri come te cercano gloria e fortuna lontano dalla sicurezza del ⟦Thendal Grove=Boschetto di Thendal⟧. Uno di loro si è accampato fuori dal ⟦Shen'dar Village=Villaggio di Shen'dar⟧, lungo la strada che dal ⟦Thendal Grove=Boschetto di Thendal⟧ porta a sud-ovest.\n\nCercalo e scopri che cosa puoi imparare da lui che ti sia utile nei tuoi viaggi.", nil, "Ben trovat<o/a>!", 0x1afc3318, 0x72c75d4e, 0x5990b6bd, nil, 0x47da9bb0, "...m." },
  [96646] = { "⟦Camping=Campeggio⟧ 101: Cucina", "Parla con ⟦Zerril Softbreeze=Zerril Brezza Leggera⟧ al ⟦Shen'dar Village=Villaggio di Shen'dar⟧ per imparare a cucinare.", "Così vuoi saperne di più sull'arte di accamparsi, eh? Ottima idea, {class}. Il primo passo per ogni avventuriero è imparare a cucinare e ad accendere un fuoco da campo.\n\nCucinare non serve solo a preparare piatti gustosi: è anche la base del tuo accampamento.", "Un buon fuoco da campo è la base di ogni buon accampamento.", "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Quello che hai imparato sono solo le basi, quindi non potrai sistemarci intorno troppi arredi.\n\nMigliora la tua abilità in Cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti dagli istruttori di altre professioni, se te la cavi nelle loro arti.", 0x61f383d0, 0x8b592b5f, 0x611be1a4, 0x20282ef3, 0x4d6e308e, "....." },
  [96652] = { "Vita da avventuriero", "Porta il diario a Brakk nei pressi di ⟦Razor Hill=Tranciacolle⟧.", "<Il diario sembra piuttosto ordinario: racconta la vita e le avventure di qualcuno di cui non hai mai sentito parlare.\n\nDiverse pagine parlano di campeggio. Sembra proprio... divertente.>", "Sei qui per imparare ad accamparti nelle terre selvagge?", "È il mio diario? Era da un po' che non lo trovavo più. Grazie, {class}.\n\nEhi, anche tu hai l'aria dell'avventuriero. Ti andrebbe di imparare ad accamparti?", 0x1afc3318, 0x19108351, 0xfeee01ed, 0xf7a7f9bd, 0xd8b07e29, "....." },
  [96655] = { "⟦Camping=Campeggio⟧ 101: Cucina", "Parla con il cuoco Torka a ⟦Razor Hill=Tranciacolle⟧ per imparare a cucinare.", "Così vuoi saperne di più sull'arte di accamparsi, eh? Ottima idea, {class}. Il primo passo per ogni avventuriero è imparare a cucinare e ad accendere un fuoco da campo.\n\nCucinare non serve solo a preparare piatti gustosi: è anche la base del tuo accampamento.", nil, "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Quello che hai imparato sono solo le basi, quindi non potrai sistemarci intorno troppi arredi.\n\nMigliora la tua abilità in Cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti dagli istruttori di altre professioni, se te la cavi nelle loro arti.", 0x61f383d0, 0x4f2cbefa, 0x611be1a4, nil, 0x4d6e308e, "...m." },
  [96656] = { "Vita da avventuriero", "Parla con Eleanor Shackleton nei pressi di Brill.", "{name}, finora ti sei <dimostrato/dimostrata> degn<o/a> di fiducia nelle tue imprese contro la ⟦Scarlet Crusade=Crociata Scarlatta⟧. Per questo ora ti affido un compito insolito.\n\nHo sentito parlare di una nuova avventuriera lungo la strada, vicino a Brill. Va' a vedere che cosa sta facendo.", nil, "Non ho niente a che fare con la ⟦Scarlet Crusade=Crociata Scarlatta⟧, se non si fosse capito. Sono solo un'avventuriera di passaggio, prima della mia prossima spedizione nelle terre selvagge.\n\nEhi, anche tu hai l'aria dell'avventuriero. Ti andrebbe di imparare ad accamparti?", 0x1afc3318, 0x60140125, 0x7846cd95, nil, 0xbb601ab5, "...m." },
  [96658] = { "⟦Camping=Campeggio⟧ 101: Cucina", "Parla con William Pickman a Brill per imparare a cucinare.", "Così vuoi saperne di più sull'arte di accamparsi, eh? Ottima idea, {class}. Il primo passo per ogni avventuriero è imparare a cucinare e ad accendere un fuoco da campo.\n\nCucinare non serve solo a preparare piatti gustosi: è anche la base del tuo accampamento.", nil, "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Quello che hai imparato sono solo le basi, quindi non potrai sistemarci intorno troppi arredi.\n\nMigliora la tua abilità in Cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti dagli istruttori di altre professioni, se te la cavi nelle loro arti.", 0x61f383d0, 0xca2cf982, 0x611be1a4, nil, 0x4d6e308e, "...m." },
  [96659] = { "Vita da avventuriero", "Consegna il ⟦Supply Bundle=Fagotto di Rifornimenti⟧ a Kaga Wildhoof nei pressi del ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "Aspetta, {name}. Ho un'altra richiesta da farti, prima che tu ci lasci.\n\nC'è un'avventuriera di nome Kaga Wildhoof che si è accampata appena fuori dal ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧. In passato mi ha aiutato molto, e ora vedo l'occasione di ricambiarla. Potresti consegnarle queste provviste?", "Sei qui per imparare ad accamparti nelle terre selvagge?", "Ti manda il capo Vento Agile? Gliel'avevo detto, allora, che non volevo nessun compenso, ma a quanto pare non mi ha ascoltata. Grazie, {class}.\n\nEhi, anche tu hai l'aria dell'avventuriero. Ti andrebbe di imparare ad accamparti?", 0x1afc3318, 0x8ee06ce3, 0xc65676fe, 0xf7a7f9bd, 0x113825f8, "....." },
  [96661] = { "⟦Camping=Campeggio⟧ 101: Cucina", "Parla con ⟦Pyall Silentstride=Pyall Passo Silente⟧ al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧ per imparare a cucinare.", "Così vuoi saperne di più sull'arte di accamparsi, eh? Ottima idea, {class}. Il primo passo per ogni avventuriero è imparare a cucinare e ad accendere un fuoco da campo.\n\nCucinare non serve solo a preparare piatti gustosi: è anche la base del tuo accampamento.", nil, "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Quello che hai imparato sono solo le basi, quindi non potrai sistemarci intorno troppi arredi.\n\nMigliora la tua abilità in Cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti dagli istruttori di altre professioni, se te la cavi nelle loro arti.", 0x61f383d0, 0xbe1a3274, 0x611be1a4, nil, 0x4d6e308e, "...m." },
  [96666] = { "Legami nella Tana", "Raggiungi il grado Amichevole nella reputazione con la Tana dei Pelledura.", nil, nil, nil, 0x1dd1aa09, 0xb3e8554e, nil, nil, nil, "..mmm" },
  [96674] = { "Pecora smarrita", "Cattura e riporta $N1 Pecora Fuggita.", nil, nil, nil, 0xcd7a4e99, 0xeed2ec15, nil, nil, nil, "..mmm" },
  [96676] = { "Rompere il sigillo del Patto di Spinanera", "Porta l'Equipaggiamento dell'⟦Alliance=Alleanza⟧ a Johun \"Cazzotto\" Dillas a Hyjal.", nil, nil, nil, 0x4428a3f9, 0xbfe6302f, nil, nil, nil, "..mmm" },
  [96735] = { "Un brindisi!?", nil, nil, nil, nil, 0x0f38dabc, nil, nil, nil, nil, ".mmmm" },
  [96770] = { "La testa del santone", "Uccidi il ⟦Witch Doctor Zum'rah=Taumaturgo Zum'rah⟧ e porta la Testa di Zum'rah all'arcimago Lan'dalock a Dalaran.", nil, nil, nil, 0x40b5f7a9, 0xb988bb33, nil, nil, nil, "..mmm" },
  [96771] = { "La vendetta degli ⟦Highborne=Alti Nobili⟧", "Recati alla Roccaforte di Krol'dok e uccidi Zalfan Lunascura.", nil, nil, nil, 0x9b77b441, 0x0210fb3d, nil, nil, nil, "..mmm" },
  [96772] = { "Il diario del drago", "Recupera il Diario di Zarla dalle profondità della Prigione di Alcaz.", nil, nil, nil, 0x8db2fe13, 0x5484c229, nil, nil, nil, "..mmm" },
  [96773] = { "L'Occhio dell'Araldo del Freddo", "Recupera l'Occhio dell'Araldo del Freddo dai ⟦Razorfen Downs=Sotterranei di Lamaspina⟧.", nil, nil, nil, 0x807d643a, 0xc02af882, nil, nil, nil, "..mmm" },
  [96774] = { "⟦Ancient Gurubashi Idol=Idolo Antico dei Gurubashi⟧", "Recupera un ⟦Ancient Gurubashi Idol=Idolo Antico dei Gurubashi⟧ dalla Drowned City.", "Gli antichi Gurubashi di Rovotorto erano maestri di oscura magia del sangue. Si dice che usassero idoli di verargento puro per incanalare quel voodoo cattivo cattivo.\n\nIl vecchio Mazu'kon darebbe qualsiasi cosa per mettere le mani su uno di quegli idoli... per studio, capisci. Che ne dici di radunare qualche amico e fare un bel colpo in quella città sommersa che spunta dal mare al largo della costa di Rovotorto? Uccidi il sacerdote dall'aria più importante che trovi là dentro, e di sicuro avrà quello che cerco.", nil, nil, 0x5f76897d, 0x4a847e99, 0xf74ccc84, nil, nil, "...mm" },
  [96775] = { "Testa di Zum'rah", "Uccidi il ⟦Witch Doctor Zum'rah=Taumaturgo Zum'rah⟧ e porta la Testa di Zum'rah a Mazu'kon a Mulgore.", nil, nil, nil, 0x8614fa93, 0x101e780b, nil, nil, nil, "..mmm" },
  [96776] = { "Radiosità di An'she", "Recupera il cristallo noto come Radiosità di An'she da Maraudon.", nil, nil, nil, 0x29fa6e04, 0x3d4715f6, nil, nil, nil, "..mmm" },
  [96779] = { "Sabotaggio alla ⟦Syndicate=Lega dei Tagliagole⟧", "Trova Lord Tomas nel ⟦Durnholde Keep=Forte Durnholde⟧, sulle ⟦Hillsbrad Foothills=Alture di Colletorto⟧, e uccidilo. Poi torna da ⟦Myrokos Silentform=Myrokos Silente⟧.", "A volte, {race}, basta un solo taglio nel punto giusto per stendere un nemico. Spesso vale lo stesso per le organizzazioni.\n\nI nostri agenti hanno individuato un bersaglio chiave tra le file della ⟦Syndicate=Lega dei Tagliagole⟧: un uomo di nome lord Tomas.\n\nHa un ruolo fondamentale nel funzionamento del ⟦Durnholde Keep=Forte Durnholde⟧, sulle ⟦Hillsbrad Foothills=Alture di Colletorto⟧. Se vuoi servire ⟦Ravenholdt=Corvolesto⟧, va' a Durnholde ed eliminalo. Più in fretta e in silenzio, meglio è.", nil, nil, 0x12459469, 0xd843986f, 0xd52e350a, nil, nil, "...mm" },
  [96781] = { "Che cosa avranno in mente?", "Ruba con destrezza il ⟦Barton's Scouting Report=Rapporto d'Esplorazione di Barton⟧ dalle tasche di Barton. Poi porta il rapporto a ⟦Myrokos Silentform=Myrokos Silente⟧ al ⟦Ravenholdt Manor=Maniero dei Corvolesto⟧.", "Abbiamo notato una squadra di esploratori della ⟦Syndicate=Lega dei Tagliagole⟧ che si aggira tra le rovine di Alterac, guidata da un uomo di nome Barton.\n\nÈ chiaro che stanno cercando qualcosa, ma non posso sapere cosa senza leggere i suoi rapporti di ricognizione.\n\nTi chiedo di sfilargli il rapporto dalle tasche, invece di ucciderlo. La morte di Barton farebbe capire alla ⟦Syndicate=Lega dei Tagliagole⟧ che li teniamo d'occhio, e di certo prenderebbero contromisure per coprire le loro tracce.\n\nSe vuoi trovarlo, molto probabilmente è con quelli della ⟦Syndicate=Lega dei Tagliagole⟧ a Strahnbrad.", nil, nil, 0xe4f9042e, 0x63217e37, 0x8e8d9103, nil, nil, "...mm" },
  [96782] = { "Recupero segreto", "Trova la ⟦Blade of House Perenolde=Lama del Casato Perenolde⟧ e l'⟦Royal Aegis of Perenolde=Egida Reale di Perenolde⟧ tra le rovine di Alterac. Poi portale a ⟦Myrokos Silentform=Myrokos Silente⟧.", "Pare che il nostro amico Barton ci abbia reso le cose molto facili. Cerca due cimeli della famiglia Perenolde tra le rovine di Alterac: la ⟦Blade of House Perenolde=Lama del Casato Perenolde⟧, una spada, e l'⟦Royal Aegis of Perenolde=Egida Reale di Perenolde⟧, uno scudo.\n\nDal rapporto, sembra che queste armi si trovino in due torri tra le rovine. Meglio prenderle prima della ⟦Syndicate=Lega dei Tagliagole⟧.\n\nGli ogre che occupano le rovine sono feroci, ma confido che saprai passare loro accanto senza dover sporcare di sangue la tua lama.", nil, nil, 0x38463dcf, 0x0dd136cc, 0xbaff77cb, nil, nil, "...mm" },
  [96783] = { "Una via d'accesso", "Ruba un'uniforme della ⟦Syndicate=Lega dei Tagliagole⟧ al ⟦Northfold Manor=Maniero dei Norten⟧ per infiltrarti nel ⟦Stromgarde Keep=Forte di Stromgarde⟧.", "Il ⟦Stromgarde Keep=Forte di Stromgarde⟧ è una delle roccaforti più grandi della ⟦Syndicate=Lega dei Tagliagole⟧. Molti degli affari più importanti dell'organizzazione si concludono dietro le sue mura.\n\nMi è giunta voce di un certo scambio tra membri della ⟦Syndicate=Lega dei Tagliagole⟧, da qualche parte negli ⟦Arathi Highlands=Altopiani d'Arathi⟧, e sono certo che i dettagli di questo scambio si trovino da qualche parte a Stromgarde.\n\nPer infiltrarti nel forte senza destare sospetti ti servirà un travestimento. Vedi se riesci a trovarne uno tra quelli della ⟦Syndicate=Lega dei Tagliagole⟧ fuori dal forte, al ⟦Northfold Manor=Maniero dei Norten⟧.", nil, nil, 0x1b0f8afe, 0xaa986c18, 0x7b8b0be2, nil, nil, "...mm" },
  [96784] = { "Maestro del travestimento", "Con il travestimento da membro della ⟦Syndicate=Lega dei Tagliagole⟧, trova qualcuno nel ⟦Stromgarde Keep=Forte di Stromgarde⟧ che sappia dell'accordo segreto.", "<Ricordi le istruzioni di Myrokos: scoprire qualcosa su un affare importante della ⟦Syndicate=Lega dei Tagliagole⟧ nel ⟦Stromgarde Keep=Forte di Stromgarde⟧. Con il tuo travestimento dovresti poter parlare con i membri della ⟦Syndicate=Lega dei Tagliagole⟧ con una certa libertà. Di sicuro qualcuno di loro sa qualcosa.>", nil, nil, 0x87afd4b0, 0x839d37e0, 0xac13dcec, nil, nil, "...mm" },
  [96785] = { "Bocca cucita", "Trova qualcosa nel ⟦Stromgarde Keep=Forte di Stromgarde⟧ che convinca Anastasia a rivelare i dettagli dell'accordo segreto.", "Chi ti credi di essere? Arrivi qui e ficchi il naso negli affari ufficiali.\n\nNon racconto niente a <un/una> pivell<o/a> sugli affari dei pezzi grossi senza un buon motivo. A meno che tu non abbia qualcosa di importante, o di prezioso, per me, non ho niente da dirti.", nil, nil, 0x21897a89, 0xe27114b7, 0xce26588b, nil, nil, "...mm" },
  [96786] = { "Trappola per la ⟦Syndicate=Lega dei Tagliagole⟧", "Manda all'aria l'accordo segreto e prendi l'oggetto destinato alla ⟦Syndicate=Lega dei Tagliagole⟧. Poi torna da ⟦Myrokos Silentform=Myrokos Silente⟧ al ⟦Ravenholdt Manor=Maniero dei Corvolesto⟧.", "Falconcrest ha mandato alcuni dei suoi a fare uno scambio nella parte meridionale del Muro di Thoradin. Non so cosa debbano ritirare. Dev'essere roba buona, perché tutti quelli coinvolti l'hanno tenuta segretissima. Credo che nemmeno quelli che la ritirano sappiano cos'è.\n\nÈ tutto quello che so. Non farmi pentire di avertelo detto.", nil, nil, 0x54ce55fd, 0x3c52e102, 0x27700057, nil, nil, "...mm" },
  [96796] = { "Officina nei boschi", "Porta il Pezzo di Ricambio all'inventrice nota come Kaylaena nella bassa Hyjal.", nil, nil, nil, 0x918594f1, 0x5041b322, nil, nil, nil, "..mmm" },
  [96797] = { "L'orfano", "Recati al ⟦Nethergarde Keep=Forte di Guardiafatua⟧ nelle ⟦Blasted Lands=Terre Devastate⟧ e trova il sergente Danneth.", nil, nil, nil, 0x06d9ea43, 0x3a64b856, nil, nil, nil, "..mmm" },
  [96798] = { "Nell'oscurità", "Trova il sergente Danneth da qualche parte nelle caverne della ⟦Serpent's Coil=Spira del Serpente⟧, a sudest del ⟦Nethergarde Keep=Forte di Guardiafatua⟧.", nil, nil, nil, 0x713cd83f, 0x9e8fb5bf, nil, nil, nil, "..mmm" },
  [96799] = { "Una pesante responsabilità", "Parla con il sergente Danneth al ⟦Nethergarde Keep=Forte di Guardiafatua⟧.", nil, nil, nil, 0xcd6be72b, 0x6157b976, nil, nil, nil, "..mmm" },
  [96800] = { "Restituzione in ritardo", "Recupera il libro ⟦The Lost Magic of the Runemasters=La Magia Perduta dei Maestri delle Rune⟧ dal ⟦Scarlet Monastery=Monastero Scarlatto⟧.", "Ehi, tu, {class}. Ho una faccenda per cui mi farebbe comodo un aiuto.\n\nGuarda caso sto scrivendo una tesi sugli antichi maestri delle rune Granmartello di Grim Batol, e mi serve un tomo in particolare per completare le mie ricerche. Secondo i nostri registri, un mago di nome Doan ha preso in prestito il libro dalla vecchia biblioteca di Dalaran prima della Terza Guerra e non l'ha mai restituito!\n\nL'arcanista Doan ora è rintanato nel ⟦Scarlet Monastery=Monastero Scarlatto⟧, nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧. Recuperami quel libro e sarai ricompensat<o/a> a dovere.", nil, nil, 0xc02ef2a8, 0x6080a32a, 0x72b14b39, nil, nil, "...mm" },
  [96811] = { "Fuga dalle ombre", "Scorta il sergente Danneth fuori dalle caverne della ⟦Serpent's Coil=Spira del Serpente⟧ e di nuovo al ⟦Nethergarde Keep=Forte di Guardiafatua⟧.", nil, nil, nil, 0xd6aa55ba, 0x81655720, nil, nil, nil, "..mmm" },
  [96812] = { "Il sangue non è acqua", "Torna dalla matrona dell'orfanotrofio Aria a Dalaran e informala dell'intenzione del sergente Danneth di prendere con sé Randal.", nil, nil, nil, 0x74278638, 0xd3e836dc, nil, nil, nil, "..mmm" },
  [96821] = { "Gambe in spalla", "Uccidi 6 Ridgeshade Creeper e 6 Ridgeshade Lurker nel sud di Durotar, poi fai rapporto a Gar'thok a ⟦Razor Hill=Tranciacolle⟧.", "Vediamo sempre meno viaggiatori da ⟦Razor Hill=Tranciacolle⟧, di questi tempi. Gli scorpidi non sono mai stati un granché, ma ora sento dire che ci sono ragni che fanno il nido lungo la strada.\n\nSe i tuoi viaggi ti portano a nord, uccidi qualche ragno lungo il cammino. Poi fai sapere a ⟦Razor Hill=Tranciacolle⟧ che la strada è un po' più sicura.", nil, "Da un po' di tempo i peoni hanno paura di viaggiare verso sud, {name}. Ora che hai ripulito un po' la strada, possiamo rimetterli al lavoro.", 0xb84a70d7, 0x3a400289, 0x05f6951d, nil, 0xd8c3f0b4, "...m." },
  [96822] = { "Per l'onore", "Raccogli l'⟦Raider's Battleaxe=Ascia da Battaglia dell'Incursore⟧, l'⟦Raider's Bow=Arco dell'Incursore⟧ e lo ⟦Raider's Shield=Scudo dell'Incursore⟧ nei dintorni del ⟦Tiragarde Keep=Forte di Tiragarde⟧, poi riportali a Turroc a ⟦Razor Hill=Tranciacolle⟧.", "Abbiamo perso molti valorosi guerrieri dell'⟦Horde=Orda⟧ quando abbiamo saccheggiato il ⟦Tiragarde Keep=Forte di Tiragarde⟧. Ora che gli umani hanno rinforzato le rovine, non possiamo recuperare le loro spoglie per onorarne degnamente la morte.\n\nVa' tra le rovine intorno al forte e cerca le armi lasciate dai nostri fratelli caduti. Le esporremo in un luogo d'onore.", "Hai fatto ciò che ti ho chiesto?", "Questi guerrieri saranno sempre ricordati, {name}. Te ne sei assicurat<o/a> tu.", 0x312a6de6, 0x12f27d5e, 0x59e8004e, 0x914533e6, 0xfc5f93be, "....." },
  [96825] = { "Un frutto che morde", "Il cuoco Torka di ⟦Razor Hill=Tranciacolle⟧ vuole che tu raccolga 8 ⟦Prickly Pear Fruit=Fico Spinoso⟧ nelle ⟦Razormane Grounds=Terre dei Chiomaguzza⟧, a ovest del villaggio.", "I nostri cacciatori e pescatori portano tanto cibo saporito per le truppe, ma è raro che portino qualcosa di dolce.\n\nHo visto un cactus che produce un frutto spinoso e gustoso. Ma cresce solo sulle colline a ovest, dove quei miserabili verrospini hanno i loro accampamenti. Supera i verrospini e portami un po' di quei frutti. E fa' attenzione: i frutti sono spinosi quanto i verrospini!", "Hai trovato i frutti?", "Li userò per preparare qualcosa di gustoso, e terrò da parte i semi per piantarli. Un giorno avremo fichi d'India in tutta Orgrimmar!", 0x5d0fb368, 0x56b9c042, 0x2c431c3a, 0xa390104c, 0x879b29b5, "....." },
  [96830] = { "Guidati dalla vista remota", "Cerca tracce dell'⟦Horde=Orda⟧ nel nordovest del ⟦Mount Hyjal=Monte Hyjal⟧.", nil, nil, nil, 0xcf7b38b1, 0xddcbdd46, nil, nil, nil, "..mmm" },
  [96833] = { "Fauci velenose", "Diffondi l'avvertimento sulla chimera aggressiva nota come Ghansurok agli altri sulla montagna.", nil, nil, nil, 0x45916c91, 0xad3860db, nil, nil, nil, "..mmm" },
  [96873] = { "Un peso al collo", "Pa'zula, al ⟦Sen'jin Village=Villaggio di Sen'jin⟧, vuole che tu raccolga 3 ⟦Luminous Residue=Residuo Luminoso⟧. Il Luminous Residue si ottiene disincantando gli Hexed Pendant lasciati dai troll delle ⟦Echo Isles=Isole dell'Eco⟧.", "I troll a est di qui hanno perso la volontà per colpa del santone Zalazane. Usa molte magie crudeli per tenere in pugno la mente dei suoi prigionieri, ma uno dei suoi trucchi preferiti è fargli indossare pendenti avvolti da malvagi incantesimi di vincolo.\n\nEsercita le tue abilità di incantamento spogliando questi pendenti della loro magia, e portami i risultati. E non metterne uno al collo per sbaglio, se ci tieni alla tua libertà!", "Che cos'hai per me, {name}?", "Ottimo lavoro. Peccato per i troll uccisi, ma ora che gli incantesimi di vincolo sono stati rimossi, i loro spiriti possono riposare.", 0xdbeec7f9, 0x2e3399cb, 0x4f2abab1, 0x777ed8a4, 0xd6297264, "....." },
  [96874] = { "L'ascia spinosa", "Ug'thok, a Orgrimmar, vuole che tu raccolga 5 Weathered Spine dalle bestie della ⟦Thunder Ridge=Fossa del Tuono⟧, insieme a 5 Pietra da Molatura Grezza.", "Hai visto le enormi bestie della ⟦Thunder Ridge=Fossa del Tuono⟧? Continuo a pensare che gli aculei sulla loro schiena sarebbero perfetti per forgiare la testa di una possente ascia. Saru si è messo a ridere quando gliel'ho detto... ma che ne sa lui!?\n\nCome parte delle tue lezioni di forgiatura, puoi darmi una mano! Portami un po' di quegli aculei, insieme a delle pietre da molatura per affilarli.", nil, nil, 0xf6bb3113, 0xf3ac90a4, 0xc9a1f75b, nil, nil, "...mm" },
  [96875] = { "Le bestie della ⟦Thunder Ridge=Fossa del Tuono⟧", "Kamari, a Orgrimmar, vuole che tu raccolga 5 ⟦Rough Lizard Hide=Pelle di Lucertola Grezza⟧ dalle bestie della ⟦Thunder Ridge=Fossa del Tuono⟧, insieme a 2 Pelle Leggera Trattata.", "Orgrimmar non smette mai di crescere, {class}. E quando i peoni hanno bisogno di pelli per rivestire le pareti e i tetti dei nostri nuovi edifici, vengono da me!\n\nLe pelli delle lucertole della ⟦Thunder Ridge=Fossa del Tuono⟧ di solito sono troppo spesse per farne armature, ma sono un ottimo materiale da costruzione. Portami un po' delle loro pelli, insieme a qualche pelle leggera trattata. Vediamo come te la cavi con il cuoio!", nil, nil, 0x6150b99e, 0x6f6f97d3, 0x8796ce18, nil, nil, "...mm" },
  [96876] = { "Lo zaino perduto di Ukor", "Riporta lo zaino a Ukor, nel sud di Durotar.", "Sulla patta dello zaino è cucito alla buona il nome \"Ukor\".", nil, nil, 0xae92df38, 0x533f75f6, 0x6bd7c611, nil, nil, "...mm" },
  [96877] = { "Lo zoccolo di Halikor", "Consegna lo ⟦Halikor's Hoof=Zoccolo di Halikor⟧ a Orgrimmar.", "L'enorme zoccolo è la prova della tua vittoria sulla possente lucertola.", "Sì?", "Che trofeo, {class}! Dev'essere stato un bel combattimento!", 0x795887e1, 0xda5a81ff, 0x4475e6e3, 0x0c07a888, 0x6e0703c3, "....." },
  [96895] = { "L'emissario dell'Alba d'Argento", "Trova il membro dell'⟦Argent Dawn=Alba d'Argento⟧ nei pressi dell'ingresso di ⟦Undercity=Sepulcra⟧.", "Non so se l'hai saputo, ma due emissari dell'⟦Argent Dawn=Alba d'Argento⟧ sono appena passati di qui. L'⟦Argent Dawn=Alba d'Argento⟧ non mi dispiace, ma non mi piace nemmeno che ficchino il naso a Tirisfal senza sorveglianza. Erano tutti e due Reietti... ma questo non mi rende meno nervoso.\n\nUno di loro è appena passato di qui, diretto a sud-est. In quella direzione c'è un gruppo di cultisti del Flagello che curiosa ai margini della città. Se quei due ne hanno sentito parlare, non c'è dubbio che abbiano attirato la loro attenzione.", nil, "Tieniti bass<o/a> e cerca di non farti vedere, {class}. Con questi cultisti non si scherza.", 0xdf68a7ca, 0x2508ce6f, 0x46ae3d29, nil, 0x5a1a2923, "...m." },
  [96896] = { "Una giusta causa", "Assisti alla conversazione tra Danitha Morr e ⟦Leonid Barthalomew the Revered=Leonid Bartholomew il Riverito⟧.", "Danitha e io abbiamo combattuto contro il Flagello in difesa di ⟦Undercity=Sepulcra⟧, quando Naxxramas ha attaccato. Quel giorno abbiamo perso molti buoni amici, compreso l'eroe da cui prende il nome questa fortezza: Garek Bandarion.\n\nForse è stato il primo Reietto a riscoprire come brandire la Luce da paladino. Mi conforta vedere la sua eredità e il suo potenziale continuare a vivere qui, con Danitha e i suoi compagni.\n\nSe solo il resto dei Reietti la pensasse allo stesso modo...", nil, "Ho intenzione di restare qui per un po' a parlare con altri amici, ma presto tornerò alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧. Se mai ti capitasse di passare da quelle parti, vieni a salutarmi. Un aiuto da avventurieri capaci ci fa sempre comodo.", 0xb14e63d6, 0x07dc792c, 0x3aaba567, nil, 0xf3a7963d, "...m." },
  [96897] = { "Il ⟦Cult of the Damned=Culto dei Dannati⟧", "Uccidi $N1 Dark Neophyte e $N2 Dark Enforcer nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "Il Flagello è una piaga per le nostre terre, e i suoi servitori vivi sono i peggiori di tutti. La gente di Tirisfal ha già abbastanza da fare tra i morti senza mente e la ⟦Scarlet Crusade=Crociata Scarlatta⟧. Se vuoi fare del bene, aiutami a farla finita con questa feccia.", nil, "Grazie per il tuo aiuto, {class}. Se non vogliamo che la storia di Lordaeron si ripeta, dobbiamo restare vigili quando spuntano minacce come questa.", 0xb7d2480d, 0x5e8b58f6, 0xcef83677, nil, 0x346b816b, "...m." },
  [96898] = { "Resti della guerra", "Raccogli $N1 Necrotic Crystal Fragment nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "Non molto tempo fa la cittadella di Naxxramas incombeva su questa città, decisa a cancellare i Reietti dalla faccia della terra. Sia i Reietti sia l'⟦Argent Dawn=Alba d'Argento⟧ persero molto, quel giorno, per assicurare il futuro dei Reietti.\n\nDurante la battaglia, il grande cristallo focalizzatore necrotico montato in cima a Naxxramas andò in frantumi e i suoi frammenti si sparsero per tutta questa zona. Sospetto che i cultisti siano qui proprio per questo. Aiutami a recuperare i frammenti e a sottrarli al Flagello.", "Ti consiglio di non toccare troppo quei cristalli. Anche frantumati ed esauriti, la magia residua di questi cristalli necrotici è molto pericolosa.", "Grazie. Questo dovrebbe rallentare gli sforzi del Flagello in questa zona. Sospetto che gli abitanti di Tirisfal continueranno a tirare fuori questi cristalli dal terreno per anni, ma togliere quelli più in vista non può che aiutare.", 0x91003497, 0x26a56997, 0x244a6298, 0x408b3f9b, 0x894f0f43, "....." },
  [96899] = { "⟦Bandarion Keep=Forte Bandarion⟧", "Incontra Leonid Barthalomew a ⟦Bandarion Keep=Forte Bandarion⟧, nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "Oggi hai fatto una gran cosa per la causa dell'⟦Argent Dawn=Alba d'Argento⟧, e te ne ringrazio. Non so quanto tu conosca la fortezza di ⟦Bandarion Keep=Forte Bandarion⟧, ma io e il mio comandante eravamo diretti laggiù per incontrare i paladini che vi risiedono. Questo prima di scoprire la presenza del Cult of the Damned.\n\nSe vuoi saperne di più sull'⟦Argent Dawn=Alba d'Argento⟧ e sulla nostra missione, cerca il mio comandante a ⟦Bandarion Keep=Forte Bandarion⟧, a nord-ovest di qui. Io resterò qui a ripulire il resto di questo pasticcio.", nil, "Questo luogo è pieno di ricordi per me. Un tempo era in mano all'⟦Argent Dawn=Alba d'Argento⟧. Fu da qui che ci preparammo a molte battaglie e scaramucce contro il Flagello, durante la sua ultima avanzata nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.\n\nQuando ci ritirammo nelle ⟦Plaguelands=Terre Infette⟧ temevo che sarebbe andato in rovina. Il mio timore era fondato, ma sono lieto che Danitha e i suoi paladini se ne siano ora presi cura.\n\nHa persino dato al forte il nome di... un amico comune.", 0x48578fb3, 0x80cd9bdb, 0x27457914, nil, 0x17570e1d, "...m." },
  [96912] = { "Campo dell'onore: settimana 1", "Vinci 10 duelli.", nil, nil, nil, 0xfe280b34, 0xc8fd5d0d, nil, nil, nil, "..mmm" },
  [96913] = { "Campo dell'onore: settimana 2", "Completa 3 battaglie nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧.", nil, nil, nil, 0xfe280b35, 0xb9209b33, nil, nil, nil, "..mmm" },
  [96914] = { "Campo dell'onore: settimana 3", "Uccidi 25 giocatori della fazione nemica nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧.", nil, nil, nil, 0xfe280b36, 0x7562eb20, nil, nil, nil, "..mmm" },
  [96930] = { "Il Corvide Capriccioso", "Torna dal Corvo Curioso.", nil, nil, nil, 0x7026db36, 0x2e21bcfe, nil, nil, nil, "..mmm" },
  [96931] = { "Verso la cima della montagna", "Tocca l'Effigie del Corvo sul ponte che domina la Culla della Tranquillità per chiamare il Dio Selvatico, Jereman.", nil, nil, nil, 0xceba0759, 0xa576d66f, nil, nil, nil, "..mmm" },
  [96939] = { "L'equilibrio tra vita e morte", "Parla con il Dio Selvatico, Marrosis.", nil, nil, nil, 0x41e7f749, 0x22f1ab29, nil, nil, nil, "..mmm" },
  [96957] = { "Dolce osso, dolce casa", "Raccogli $N1 Osso Sbiancato dal Sole.", nil, nil, nil, 0xd411e8a7, 0x14ee20c3, nil, nil, nil, "..mmm" },
  [96959] = { "I falò del maestro di spade", "Accendi i due falò a Dae'gun e torna da Yashiro.", nil, nil, nil, 0x6ddccd05, 0x271f18a0, nil, nil, nil, "..mmm" },
  [96964] = { "Una creatura astuta", "Parla con il Dio Selvatico Renalard.", nil, nil, nil, 0xcb2372fd, 0xfb7c78fb, nil, nil, nil, "..mmm" },
  [96971] = { "Fregare un demone", "Raccogli $N1 Scorte Abbandonate.", nil, nil, nil, 0x8a1c54ab, 0x3d8fcac2, nil, nil, nil, "..mmm" },
  [96978] = { "Cacciagione violenta", "Parla con il Dio Selvatico, Kala'th.", nil, nil, nil, 0xfb4b81d5, 0x82f85488, nil, nil, nil, "..mmm" },
  [96979] = { "Rinfresco sacro", "Riempi la borraccia di Galvinquam Leafsyre alla cascata più avanti.", nil, nil, nil, 0xcef841cb, 0x6ed72776, nil, nil, nil, "..mmm" },
  [96982] = { "Il tuo primo ⟦Riding Kodo=Kodo Cavalcabile⟧", "Ispeziona i Kodo Cavalcabili per scegliere la tua prima cavalcatura.", nil, nil, nil, 0x2f8c7c80, 0x9ca0fd73, nil, nil, nil, "..mmm" },
  [96983] = { "Il Passovento di Yashiro", "Fatti strada combattendo a Dae'gun insieme a Yashiro.", nil, nil, nil, 0x727b69f3, 0x30aead77, nil, nil, nil, "..mmm" },
  [96984] = { "Il cuore dello sconvolgimento", "Raccogli la ⟦Arcane Mote=Particella Arcana⟧ nella città di Dalaran per il magus Wordeen Bagliovuoto, al ⟦Tarren Mill=Mulino di Tarren⟧.", "Forse non hai a cuore i nostri interessi, ma non rifiuterò un paio di mani in più. E se Dalaran cade, trascina con sé tutto quanto, compresa la tua ⟦Undercity=Sepulcra⟧.\n\nDunque il tuo benefattore vuole entrare? D'accordo. Infonderò la tua chiave perché superi le mie protezioni, così potrai entrare in città. Una volta dentro, raggiungimi alla Violet Citadel, dove è cominciato tutto. Con tutto quello che sta succedendo, il Kirin Tor sarà troppo occupato per fermarti.\n\nArraffa quello che vuoi, ma qualunque cosa accada, la nostra priorità è evitare una catastrofe.", nil, nil, 0x0ac2f4b9, 0xe3ed9b69, 0x6b205a30, nil, nil, "...mm" },
  [96986] = { "Il cavaliere delle tombe", "Sconfiggi Atrexis the Grave Knight nella città di Dalaran per Melisara, al ⟦Tarren Mill=Mulino di Tarren⟧.", "Nelle viscere della città dei maghi, a nord, si nasconde un traditore della nostra specie. Un negromante di inquietante talento. Sta radunando un esercito di non morti proprio sotto il naso del Kirin Tor.\n\nNon m'importa della sorte della città dei maghi, {name}, ma questo cavaliere delle tombe sputa in faccia a tutto ciò che noi Reietti rappresentiamo. Fallo fuori. Mostragli che nessuno è fuori dalla portata della Dama Oscura.", nil, "Ottimo lavoro. Quella bestia non è degna di camminare tra i morti. Che giaccia sotto di loro.", 0x9b982b21, 0x24bf35e3, 0x65fb9835, nil, 0x68b23b00, "...m." },
  [96987] = { "Un'istruzione opportunista", "Recupera il Founding of Dalaran nella città di Dalaran per Rexxie Copperclutch, vicino all'ingresso delle fogne.", "Ma guarda, qualcuno che la pensa come me in fatto di affari. Intrufolarsi a Dalaran in tempi così burrascosi? Tsk tsk.\n\n<Un/Una> {race} come piace a me!\n\nMentre i nostri amici maghi sono occupati, magari potremmo trovarci qualche tesoro «smarrito». Hanno intere biblioteche dedicate alle loro raffinate magie arcane. Se mi porti uno dei loro tomi segreti, potrei rivenderlo a peso d'oro. E dividiamo i profitti.\n\nEhi, ehi, non guardarmi così. Neanche tu sei qui in gita scolastica. Ci stai o no?", "Allora? L'hai trovata la loro biblioteca? Ci dev'essere qualcosa di buono là dentro.", "Forse non avrei dovuto mandare un tirapiedi a cercare manufatti inestimabili. Questo vale a malapena la pena di venderlo in un chiosco per turisti! Che hai fatto, hai preso il primo libro che sporgeva dagli altri?\n\nLascia perdere. Magari posso spruzzarlo d'oro e dire che apparteneva a un arcimago o roba simile.", 0xcb4d2d84, 0xc41dad65, 0x159f4617, 0x19998649, 0xdb720c34, "....." },
  [96988] = { "Fonte di potere", "Raccogli $N1 Cracked Sentry Core nella città di Dalaran per il dottor Martin Felben, a ⟦Undercity=Sepulcra⟧.", "Con la città di Dalaran assediata dai suoi stessi costrutti, è l'occasione perfetta per, diciamo, prendere in prestito qualche campione.\n\nImmagina un esercito di abomini alimentati dall'arcano. La Dama Oscura non avrebbe altra scelta che riconoscere la mia abilità alchemica. Magari mi metterebbe perfino a capo della Royal Apothecary Society?\n\nVa' in città e trova i nuclei dei costrutti. Difficilmente te li daranno di loro spontanea volontà, quindi fa' ciò che devi.", "Il pregio di questi nuclei è che sono potenti. Il guaio è che, per lo stesso motivo, sono potenti anche i costrutti. Buona fortuna.", "Incrinato. Incrinato. INCRINATO.\n\nNon posso usarne neanche uno! Ti avevo detto di disattivare le sentinelle, non di annientarle! Quanto potevano essere pericolose?\n\nI miei sogni di abomini arcani sono in stallo. Per ora.", 0x64b20fc1, 0x8337ed29, 0xa537f845, 0x406d6cfd, 0xb95a6f40, "....." },
  [96989] = { "Il tuo primo ⟦Riding Raptor=Raptor Cavalcabile⟧", "Ispeziona i Raptor Cavalcabili per scegliere la tua prima cavalcatura.", nil, nil, nil, 0x5d01635c, 0xd621c0a6, nil, nil, nil, "..mmm" },
  [96991] = { "Assistenza sul sentiero", "Consegna gli Effetti Personali di Galvinquam a Marn Euhron alla Sommità.", nil, nil, nil, 0x0487ac9f, 0x9af8f93c, nil, nil, nil, "..mmm" },
  [96992] = { "Rifornimento", "Cerca tra gli edifici bruciati nella Culla della Tranquillità $N1 Staffa di Metallo e $N2 Chiodo, poi torna da Johun \"Cazzotto\" Dillas a Hyjal.", nil, nil, nil, 0x9e2e3b44, 0x4554daea, nil, nil, nil, "..mmm" },
  [96994] = { "Il tuo primo ⟦Riding Wolf=Lupo Cavalcabile⟧", "Ispeziona i Lupi Cavalcabili per scegliere la tua prima cavalcatura.", nil, nil, nil, 0x312823d3, 0x8e279f41, nil, nil, nil, "..mmm" },
  [96996] = { "Il tuo primo Calcaventi da cavalcare", "Ispeziona i Calcaventi da cavalcare per scegliere la tua prima cavalcatura.", nil, nil, nil, 0x0451b7f8, 0xd4f44937, nil, nil, nil, "..mmm" },
  [96997] = { "Un destriero in morte come in vita", "Ispeziona i cavalli non morti da cavalcare per scegliere la tua prima cavalcatura.", nil, nil, nil, 0xcea878f9, 0x3be62de1, nil, nil, nil, "..mmm" },
  [96998] = { "Colori tribali", "Porta la Fascia del Pittore di Guerra a qualcuno che potrebbe riconoscerla.", nil, nil, nil, 0xfbe8a5d2, 0xa798a01b, nil, nil, nil, "..mmm" },
  [96999] = { "Restituire la fascia", "Porta la Fascia del Pittore di Guerra a qualcuno al ⟦Sen'jin Village=Villaggio di Sen'jin⟧.", nil, nil, nil, 0x8926bb2c, 0x6e7f2ad0, nil, nil, nil, "..mmm" },
})
